                        <FormProvider
                            style={[styles.flexGrow1, styles.mh5]}
                            formID={ONYXKEYS.FORMS.WORKSPACE_NEW_TAX_FORM}
                            onSubmit={submitForm}
                            validate={validateForm}
                            submitButtonText={translate('common.save')}
                            enabledWhenOffline
